{{
  (() => {
    const factures = listeFacturesDashboard.data?.items || [];

    // Si pas de factures, retourner des données vides
    if (!factures.length) {
      return [{
        name: "Aucune donnée",
        data: [{ x: "Aucune facture", y: 0 }]
      }];
    }

    const parFournisseur = {};
    factures.forEach(f => {
      const frn = (f.fournisseur || 'Inconnu').trim();
      if (!parFournisseur[frn]) {
        parFournisseur[frn] = 0;
      }
      parFournisseur[frn] += (f.montant_ttc || 0);
    });

    const sorted = Object.entries(parFournisseur)
      .filter(([nom, total]) => total > 0) // Filtrer les montants nuls
      .sort((a, b) => b[1] - a[1])
      .slice(0, 5);

    // Si après filtrage il n'y a rien
    if (!sorted.length) {
      return [{
        name: "Aucune donnée",
        data: [{ x: "Aucune facture", y: 0 }]
      }];
    }

    return [{
      name: "Montant TTC",
      data: sorted.map(([nom, total]) => ({
        x: nom,
        y: Math.round(total)
      }))
    }];
  })()
}}

